UdonSharp minimal example:
using UdonSharp;
using UnityEngine;
using VRC.SDKBase;
using VRC.Udon;
#if !COMPILER_UDONSHARP && UNITY_EDITOR
using UnityEditor;
using UdonSharpEditor;
using System;
using System.Linq;
#endif
public class Test : UdonSharpBehaviour {
	public VRC.Udon.Common.UdonInputEventArgs _udonInputEventArgs; // Breaks serialization, causing _value to always be true - works in Unity editor's play mode, but broken in VRC client.
	public bool _value = true;
	void Start() => LogState();
	void LogState() => Debug.Log($"Start() :: gameObject: {this.gameObject.name}, _value: {this._value}");
}
#if !COMPILER_UDONSHARP && UNITY_EDITOR
[CustomEditor(typeof(Test), true)]
public class TestEditor : Editor {
	private Test proxy;
	private bool isProxyBehaviour = false;
	public void Awake() {
		proxy = (Test)target;
		isProxyBehaviour = (target is UdonSharpBehaviour b) && UdonSharpEditorUtility.IsProxyBehaviour(b);
		// Convert Script To Behaviour Automatically
		if(!EditorApplication.isPlaying && (target is UdonSharpBehaviour behaviour) && !UdonSharpEditorUtility.IsProxyBehaviour(behaviour)) {
			UdonSharpEditorUtility.ConvertToUdonBehaviours(Array.ConvertAll(targets, e => e as UdonSharpBehaviour).Where(e => e != null && !UdonSharpEditorUtility.IsProxyBehaviour(e)).ToArray());
			return;
		}
		if(!isProxyBehaviour) return;
	}
	public override void OnInspectorGUI() {
		if(!isProxyBehaviour || UdonSharpGUI.DrawDefaultUdonSharpBehaviourHeader(target)) return;
		proxy._value = EditorGUILayout.Toggle("Value", proxy._value);
	}
}
#endif
